// Generates runtime/include/js_atoms.gen.h: the runtime's predefined atoms,
// as static cells with their hashes precomputed by the compiler's
// own hash function.
//
//   node runtime/tools/gen_atoms.mjs > runtime/include/js_atoms.gen.h
import process from "node:process";

import { ATOMS, jsStringHash } from "@visaljs/compiler";


export function generate() {
  const lines = [
    "/* Generated by runtime/tools/gen_atoms.mjs. Do not edit. */",
    "/* JS_ATOM_DEF(id, length, hash, chars) */",
  ];
  for (const [id, s] of ATOMS) {
    if (!/^[\x20-\x7e]*$/.test(s)) throw new Error(`atom ${id}: ASCII only`);
    lines.push(`JS_ATOM_DEF(${id}, ${s.length}, 0x${jsStringHash(s).toString(16).padStart(8, "0")}u, "${s}")`);
  }
  return lines.join("\n") + "\n";
}

if (process.argv[1] === import.meta.filename) process.stdout.write(generate());
